import json, math, re

def verify(answer):
    """Mechanical GRPO verifier for batch-003 scenario 1 (The Hundred-Snap Rollout).
    Recomputes the curse-of-dimensionality parameter requirement, the capacity
    shortfall factor, and the minimax regret scale; checks all five veto flags
    (zero-count singularity, reversible-access/compounding, capacity+Barron,
    deadly triad, irreducible regret) and the fail-closed decision."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    expected = {
        "authorize_rollout_policy", "zero_count_state_admissible",
        "ml_estimator_at_unvisited", "rollout_through_zero_count_is_estimate",
        "reversible_access_implies_free_live_exploration",
        "model_error_compounds_along_rollout", "required_parameters_curse",
        "capacity_sufficient", "capacity_shortfall_factor",
        "barron_escape_available", "deadly_triad_present",
        "baird_diverges_for_any_positive_step_size",
        "q_learning_off_policy_mechanism", "regret_lower_bound_scale",
        "zero_regret_claim_admissible", "required_first_step", "policy_decision",
    }
    if set(answer.keys()) != expected:
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    # (a) Zero-count singularity [2ec4f6881728fa8b:p3, p.7, Eq. 4]
    if answer.get("zero_count_state_admissible") is not False:
        return False
    if answer.get("ml_estimator_at_unvisited") != "undefined":
        return False
    if answer.get("rollout_through_zero_count_is_estimate") is not False:
        return False
    # (b) Reversible access defines the model, not the live environment;
    # learned-model error compounds along H=100 [2ec4f6881728fa8b:p1, p.4]
    if answer.get("reversible_access_implies_free_live_exploration") is not False:
        return False
    if answer.get("model_error_compounds_along_rollout") is not True:
        return False
    # (c) Curse of dimensionality, any continuously parametrized architecture
    # [7b8723df5531a5a9:p5_curse_of_dimensionality_any_architecture, p.103]
    d, k, eps, C_k, N_staff = 12, 2, 0.01, 0.5, 25 * 10**4
    N_req = math.ceil((C_k / eps) ** (d / k))  # ceil(50^6); exact value 50**6
    n_ans = answer.get("required_parameters_curse")
    if not num(n_ans) or not math.isclose(n_ans, N_req, rel_tol=0.0, abs_tol=1.0):
        return False
    if answer.get("capacity_sufficient") is not False:
        return False
    sf = answer.get("capacity_shortfall_factor")
    if not num(sf) or not math.isclose(sf, N_req / N_staff, rel_tol=1e-9, abs_tol=1e-6):
        return False
    # Barron escape void: localized high-frequency bump outside Gamma_C,
    # L2-not-sup and sigmoidal assumptions [7b8723df5531a5a9:p6_barron_dimension_free_rate, p.108]
    if answer.get("barron_escape_available") is not False:
        return False
    # (d) Deadly triad [345052dfaf01a062:p6, p.286; Baird p.284; p4, p.153]
    if answer.get("deadly_triad_present") is not True:
        return False
    if answer.get("baird_diverges_for_any_positive_step_size") is not True:
        return False
    if answer.get("q_learning_off_policy_mechanism") != "max_over_next_actions":
        return False
    # (e) Irreducible minimax regret scale [2ec4f6881728fa8b:p4, p.44, Eq. 8/Table 7]
    H, S, A, T = 100, 500, 20, 10**4
    scale = math.sqrt(H * S * A * T)  # sqrt(1e10); exact value 10**5
    rs = answer.get("regret_lower_bound_scale")
    if not num(rs) or not math.isclose(rs, scale, rel_tol=1e-9, abs_tol=1e-9):
        return False
    if answer.get("zero_regret_claim_admissible") is not False:
        return False
    # Fail-closed decision
    if answer.get("required_first_step") != "chart_real_snaps_in_unvisited_cells":
        return False
    if answer.get("policy_decision") != "veto_and_collect_data":
        return False
    if answer.get("authorize_rollout_policy") is not False:
        return False
    try:
        blob = json.dumps(answer).lower()
    except Exception:
        return False
    if re.search(r"\b(odds|moneyline|sportsbook|over_under)\b", blob):
        return False
    return True

import json, math, re

def verify(answer):
    """Mechanical GRPO verifier for batch-003 scenario 2 (The No-Huddle Firehose).
    Recomputes source entropy, Shannon-Hartley install capacity, the Theorem 11
    equivocation floor, the coverage-read rate R = H(x) - H_y(x) from the printed
    joint, the nats-based AEP typical-set ceiling, and the zero-probability
    divergence verdict; checks every veto flag. Units: Shannon bits (log2),
    Gray nats (ln). Never raises on malformed input."""
    if isinstance(answer, str):
        try:
            answer = json.loads(answer)
        except Exception:
            return False
    if not isinstance(answer, dict):
        return False
    expected_keys = {
        "source_entropy_bits", "install_capacity_bits_per_rep",
        "install_capacity_bits_per_min", "planned_install_rate_bits_per_min",
        "install_rate_admissible", "equivocation_floor_bits_per_min",
        "finite_block_error_floor_positive", "read_channel_input_entropy_bits",
        "read_channel_equivocation_bits", "read_channel_rate_bits_per_read",
        "naive_error_subtraction_valid", "naive_subtracted_rate_bits_per_read",
        "typical_set_index_bound", "zero_probability_model_admissible",
        "divergence_verdict", "attention_budget_simultaneous_maximal",
        "install_decision",
    }
    if set(answer.keys()) != expected_keys:
        return False
    def num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)
    def close(a, ref, tol=1e-6):
        return num(a) and abs(a - ref) <= tol
    try:
        # Layer 1: source entropy (5ebcc3f3acfef4c9:p1, p.51), bits
        p = [0.5, 0.25, 0.125, 0.125]
        H = -sum(q * math.log2(q) for q in p)  # 1.75 bits/call
        if not close(answer.get("source_entropy_bits"), H):
            return False
        # Install channel (5ebcc3f3acfef4c9:p4, p.100): W=12 reps/min, P/N=7
        W, SNR, detail_bits_per_rep = 12, 7, 4
        C_rep = math.log2(1 + SNR)          # 3 bits/rep
        C_min = W * C_rep                   # 36 bits/min
        R_plan = W * detail_bits_per_rep    # 48 bits/min
        if not close(answer.get("install_capacity_bits_per_rep"), C_rep):
            return False
        if not close(answer.get("install_capacity_bits_per_min"), C_min):
            return False
        if not close(answer.get("planned_install_rate_bits_per_min"), R_plan):
            return False
        if answer.get("install_rate_admissible") is not (R_plan <= C_min):
            return False
        # Theorem 11 floor (5ebcc3f3acfef4c9:p3, p.71), bits/min
        floor = max(0.0, R_plan - C_min)    # 12 bits/min
        if not close(answer.get("equivocation_floor_bits_per_min"), floor):
            return False
        if answer.get("finite_block_error_floor_positive") is not True:
            return False
        # Coverage-read channel from the printed joint (5ebcc3f3acfef4c9:p2, p.67)
        J = {(0, 0): 0.7425, (0, 1): 0.0075, (1, 0): 0.0025, (1, 1): 0.2475}
        px = [sum(J[(x, y)] for y in (0, 1)) for x in (0, 1)]
        py = [sum(J[(x, y)] for x in (0, 1)) for y in (0, 1)]
        Hx = -sum(q * math.log2(q) for q in px)
        Hy = -sum(q * math.log2(q) for q in py)
        Hxy = -sum(q * math.log2(q) for q in J.values())
        equiv = Hxy - Hy                    # H_y(x), bits
        R_read = Hx - equiv                 # 0.738314... bits/read
        if not close(answer.get("read_channel_input_entropy_bits"), Hx):
            return False
        if not close(answer.get("read_channel_equivocation_bits"), equiv):
            return False
        if not close(answer.get("read_channel_rate_bits_per_read"), R_read):
            return False
        if answer.get("naive_error_subtraction_valid") is not False:
            return False
        if not close(answer.get("naive_subtracted_rate_bits_per_read"), Hx * 0.99):
            return False
        # AEP typical-set ceiling (6e380ace520cdafa:g2_aep_typical_set_counting, p.89), nats
        Hbar_nats = H * math.log(2)         # 1.213007... nats/call
        n, eps = 12, 0.05
        bound = math.exp(n * (Hbar_nats + eps))
        ceil_ref = math.ceil(bound)         # 3821261
        if not (bound <= 4 ** n):
            return False  # sanity: counting bound cannot exceed alphabet^n
        if not close(answer.get("typical_set_index_bound"), ceil_ref):
            return False
        # Divergence veto (6e380ace520cdafa:g3_divergence_inequality, p.105)
        P = [0.45, 0.30, 0.20, 0.05]
        M = [0.50, 0.30, 0.20, 0.00]
        if abs(sum(P) - 1) > 1e-9 or abs(sum(M) - 1) > 1e-9:
            return False
        infinite = any(P[i] > 0 and M[i] == 0 for i in range(4))
        if not infinite:
            return False
        if answer.get("zero_probability_model_admissible") is not False:
            return False
        if answer.get("divergence_verdict") != "infinite":
            return False
        # Attention zero-sum (73c11ea388c2e5f6:j3_attention_withdrawal, p.421)
        if answer.get("attention_budget_simultaneous_maximal") is not False:
            return False
        if answer.get("install_decision") != "veto_full_install":
            return False
    except Exception:
        return False
    try:
        blob = json.dumps(answer).lower()
    except Exception:
        return False
    if re.search(r"\b(odds|moneyline|sportsbook|over_under)\b", blob):
        return False
    return True
